395	export const serializeSpace = (space: Space): SerializedSpace => {
396	  const seen = new WeakSet<object>();
397	  if (typeof space === "object" && space !== null) {
398	    seen.add(space);
399	  }
400	  return passThroughSpace(space as unknown as Record<string, unknown>, seen);
401	};
402	
403	// ---------------------------------------------------------------------------
404	// Per-content-arm serializers
405	// ---------------------------------------------------------------------------
406	//
407	// One hand-shaped function per content arm we forward from the SDK's
408	// `Content` discriminated union (see KNOWN_CONTENT_TYPES for the subset).
409	// Each function projects the SDK shape onto the wire by:
410	//   - dropping function thunks (`read()`, `stream()`, async OG accessors) —
411	//     they can't cross the HTTPS boundary, and `JSON.stringify` silently
412	//     drops them anyway; doing it explicitly here keeps the type accurate;
413	//   - dropping server-internal fields (filesystem `path` on attachment /
414	//     voice) so they don't leak to customer endpoints;
415	//   - projecting nested SDK objects (`User`, nested `Message`) to the same
416	//     `{ id, platform }` / slim-ref shapes the rest of the wire uses;
417	//   - keeping every other customer-useful field unchanged.
418	//
419	// `custom` and `contact` are the two arms where the provider's `raw` IS
420	// useful — `custom.raw` IS the entire payload by design, and `contact.raw`
421	// carries the provider-native vCard / platform blob that customers asked
422	// us to pass through. Both go through `serializeAnyInner` for JSON safety
423	// (Date → ISO, functions stripped, cycles guarded), but nothing else is
424	// filtered.
425	//
426	// Webhook = notification + metadata for self-service retrieval. We
427	// deliberately ship URLs / mimeTypes / sizes and let the customer pull
428	// bytes (or OG metadata) themselves when they need them — keeps the wire
429	// small and avoids tying delivery latency to the slowest target site.
430	
