432	
433	const isTextContent = (
434	  content: unknown
435	): content is { type: "text"; text: string } =>
436	  typeof content === "object" &&
437	  content !== null &&
438	  (content as { type?: unknown }).type === "text" &&
439	  typeof (content as { text?: unknown }).text === "string";
