/**
 * Top-level content dispatcher. Routes a `ContentLike` object to the
 * matching per-arm serializer based on `type`. Used by:
 *
 *   - `serializeMessage` for the `messages` arm's `content` field;
 *   - `serializeReply` / `serializeEdit` / `serializeEffect` for the
 *     recursive `content` field they each carry;
 *   - `serializeAnyInner` for any content-shaped object that surfaces
 *     on the generic dynamic-events path. Routing every known arm through
 *     the same dispatcher keeps the wire format consistent across the
 *     `messages` arm and any future dynamic event that ships content.
 *
 * Unknown arms (a future SDK content type not yet covered here) fall
 * through to a generic projection that keeps `type` plus any JSON-safe
 * fields, so a webhook deploy isn't required when the SDK adds a new
 * arm. The {@link SerializedUnknownContent} tail of
 * {@link SerializedContent} captures this case at the type level.
 */
const serializeContent = (
  content: ContentLike,
  seen: WeakSet<object>
): SerializedContent => {
  // Cycle guard for recursive arms (reply/edit/effect, plus custom/contact
  // whose `raw` is opaque). serializeAnyInner must NOT pre-add content
  // records — the dispatcher owns the seen-add.
  if (seen.has(content)) {
    return { type: content.type } as SerializedUnknownContent;
  }
  seen.add(content);
  switch (content.type) {
    case "text":
      return serializeText(content as unknown as { text: string });
    case "custom":
      return serializeCustom(content as unknown as { raw: unknown }, seen);
    case "attachment":
      return serializeAttachment(
        content as unknown as {
          id?: string;
          mimeType: string;
          name: string;
          size?: number;
        }
      );
    case "voice":
      return serializeVoice(
        content as unknown as {
          duration?: number;
          mimeType: string;
          name?: string;
          size?: number;
        }
      );
    case "contact":
      return serializeContact(
        content as unknown as Contact & { raw?: unknown },
        seen
      );
    case "richlink":
      return serializeRichlink(content as unknown as { url: string });
    case "reaction":
      return serializeReaction(
        content as unknown as { emoji: string; target: Message }
      );
    case "group":
      return serializeGroup(content as unknown as { items: Message[] });
    case "poll":
      return serializePoll(
        content as unknown as {
          options: { title: string }[];
          title: string;
        }
      );
    case "poll_option":
      return serializePollOption(
        content as unknown as {
          option: { title: string };
          poll: { options: { title: string }[]; title: string };
          selected: boolean;
          title: string;
        }
      );
    case "effect":
      return serializeEffect(
        content as unknown as { content: ContentLike; effect: string },
        seen
      );
    case "typing":
      return serializeTyping(content as unknown as { state: "start" | "stop" });
    case "reply":
      return serializeReply(
        content as unknown as { content: ContentLike; target: Message },
        seen
      );
    case "edit":
      return serializeEdit(
        content as unknown as { content: ContentLike; target: Message },
        seen
      );
    case "rename":
      return serializeRename(content as unknown as { displayName: string });
    case "addMember":
      return serializeAddMember(content as unknown as { members: string[] });
    case "removeMember":
      return serializeRemoveMember(content as unknown as { members: string[] });
    case "leaveSpace":
      return serializeLeaveSpace();
    case "avatar": {
      if (isKnownAvatarAction(content.action)) {
        return serializeAvatar(
          content as unknown as Parameters<typeof serializeAvatar>[0]
        );
      }
      // Unknown/incomplete action kind — same projection as unknown arms.
      const projected = serializeObject(content, seen);
      return { ...projected, type: content.type } as SerializedUnknownContent;
    }
    default: {
      // Unknown future arm — project generically, keep `type`.
      const projected = serializeObject(content, seen);
      return { ...projected, type: content.type } as SerializedUnknownContent;
    }
  }
};

